/** Terminates the clients, then stops each server once it has seen its sockets close, so no close is logged late. */
export async function closeEngines(servers: HalServer[], clients: WebSocket[]): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    for (let attempt = 0; attempt < 50 && hal.wss.clients.size > 0; attempt++) {
      await new Promise(resolve => setTimeout(resolve, 10));
    }
    await hal.stop();
  }
}
